#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>> ops;
    auto apply=[&](int x,int y){
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
        ops.push_back({x,y});
    };
    for(int i=0;i<n-1;i++){
        int j=-1;
        for(int k=i;k<n;k++) if(p[k]==i+1){j=k;break;}
        if(j==i) continue;
        int rem=n-i; // working with positions i..n-1
        // Bring p[j] to position i
        // Step 1: bring to position 0
        if(j>0){
            apply(j, n-j); // rotation: last n-j go front
        }
        // Now target is at position 0
        // Step 2: bring to position i
        if(i>0){
            if(i<n-1){
                apply(i, n-i); // rotation
                // element at 0 goes to position n-i (since first i go to end)
                // Actually element at 0 is in first x=i block, goes to end at position n-1
                // Hmm, need: apply(n-i, i) to put it at position i
                // Undo and redo
            }
            // apply(n-i, i): element at 0 in first n-i block, goes to pos n-1. Not right either.
            apply(1, n-1-i);
            // pos 0 goes to last of result = pos n-1. Then rotate to pos i:
            apply(n-1-i, i+1); // but need i+1 + n-1-i = n, ok full rotation
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
